import {ToolRegistry} from './registry.js';
import type {ToolResponse} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('rejects missing required location without invoking the executor', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {
        name: 'forecast',
        description: 'Forecast lookup',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        calls += 1;
        return 'clear';
      }
    );

    const response: ToolResponse = await registry.execute('forecast', {});

    expect({
      calls,
      hasLocation: response.result.includes('location'),
      mentionsRequired: /required/i.test(response.result),
    }).toEqual({calls: 0, hasLocation: true, mentionsRequired: true});
  });

  it('passes valid input with extra properties through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const received: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'forecast',
        description: 'Forecast lookup',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
            units: {type: 'string', enum: ['celsius', 'fahrenheit'], default: 'celsius'},
          },
          required: ['location'],
        },
      },
      async input => {
        received.push(input);
        return 'ok';
      }
    );

    const payload = {location: 'Berlin', extraTag: 'keep-me'};
    await registry.execute('forecast', payload);

    expect(received).toEqual([{location: 'Berlin', extraTag: 'keep-me'}]);
  });

  it('rejects wrong-typed input naming field path and expected type without offending value', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {
        name: 'counter_tool',
        description: 'Accepts a string label',
        inputSchema: {
          type: 'object',
          properties: {label: {type: 'string'}},
          required: ['label'],
        },
      },
      async () => {
        calls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('counter_tool', {label: 987654});

    expect({
      calls,
      mentionsField: response.result.includes('label'),
      mentionsType: response.result.includes('string'),
      leaksValue: response.result.includes('987654'),
    }).toEqual({calls: 0, mentionsField: true, mentionsType: true, leaksValue: false});
  });

  it('rejects enum violations without leaking identifying values to result or logs', async () => {
    const logLines: string[] = [];
    const capture = (category: string, message: string, fields?: Record<string, unknown>) => {
      logLines.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {debug: capture, info: capture, warn: capture, error: capture};
    setLogger(logger);

    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'unit_tool',
        description: 'Unit selector',
        inputSchema: {
          type: 'object',
          properties: {
            units: {type: 'string', enum: ['celsius', 'fahrenheit']},
            secretToken: {type: 'string'},
          },
          required: ['units'],
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('unit_tool', {
      units: 'secret-kelvin-value',
      secretToken: 'tok-998877',
    });

    expect({
      mentionsUnits: response.result.includes('units'),
      leaksEnumValue: response.result.includes('secret-kelvin-value'),
      leaksToken: response.result.includes('tok-998877'),
      logsLeakValue: logLines.some(line => line.includes('secret-kelvin-value') || line.includes('tok-998877')),
    }).toEqual({mentionsUnits: true, leaksEnumValue: false, leaksToken: false, logsLeakValue: false});
  });

  it('compiles a static tool schema once across ten execute calls', async () => {
    const registry = new ToolRegistry();
    const schema = {type: 'object', properties: {city: {type: 'string'}}, required: ['city']};
    let schemaReads = 0;
    const definition: ToolDefinition = {name: 'static_weather', description: 'Static schema', inputSchema: {}};
    Object.defineProperty(definition, 'inputSchema', {
      enumerable: true,
      get() {
        schemaReads += 1;
        return schema;
      },
    });

    registry.register(definition, async input => String(input.city));

    const results: string[] = [];
    for (let index = 0; index < 10; index += 1) {
      const response = await registry.execute('static_weather', {city: 'Oslo'});
      results.push(response.result);
    }

    expect({schemaReads, callCount: results.length}).toEqual({schemaReads: 1, callCount: 10});
  });

  it('validates function-valued tool definitions against the current schema and caches per object', async () => {
    const registry = new ToolRegistry();
    const citySchema = {type: 'object', properties: {city: {type: 'string'}}, required: ['city']};
    const postalSchema = {type: 'object', properties: {postalCode: {type: 'string'}}, required: ['postalCode']};
    let activeSchema: Record<string, unknown> = citySchema;

    registry.register(
      () => ({name: 'dynamic_geo', description: 'Geo lookup', inputSchema: activeSchema}),
      async input => JSON.stringify(input)
    );

    const firstValid = await registry.execute('dynamic_geo', {city: 'Paris'});
    activeSchema = postalSchema;
    const staleRejected = await registry.execute('dynamic_geo', {city: 'Paris'});
    const secondValid = await registry.execute('dynamic_geo', {postalCode: '75001'});

    expect({
      firstAccepted: firstValid.result === '{"city":"Paris"}',
      staleRejectedForPostal: staleRejected.result.includes('postalCode') && /required/i.test(staleRejected.result),
      secondAccepted: secondValid.result === '{"postalCode":"75001"}',
    }).toEqual({firstAccepted: true, staleRejectedForPostal: true, secondAccepted: true});
  });

  it('throws Unknown tool for an unregistered tool name', async () => {
    const registry = new ToolRegistry();
    const outcome = await registry
      .execute('missing_tool', {})
      .then(() => 'resolved')
      .catch((error: Error) => error.message);

    expect(outcome).toBe('Unknown tool: missing_tool');
  });
});

